import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl, sinusoidal modulation, and a linear term with pairwise interactions.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + linear_interactions(x)

    quadratic_bowl(x) = sum(0.5 * x_i^2 + 0.1 * x_i^3)  (introduces skew)
    sinusoidal_modulation(x) = 0.1 * sum(sin(2 * pi * x_i))  (creates local minima and influences nbc features)
    linear_interactions(x) = 0.05 * sum(x_i * x_j for all i < j) + 0.01 * sum(x_i)    (introduces linear interactions)
    """
    def quadratic_bowl(x):
        return np.sum(0.5 * x**2 + 0.1 * x**3)

    def sinusoidal_modulation(x):
        return 0.1 * np.sum(np.sin(2 * np.pi * x))

    def linear_interactions(x):
        n = len(x)
        interaction_sum = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                interaction_sum += x[i] * x[j]
        return 0.05 * interaction_sum + 0.01*np.sum(x) #Adjusted the interaction Strength

    return quadratic_bowl(x) + sinusoidal_modulation(x) + linear_interactions(x)
